const cfg = $items('Ingestion config', 0, 0)[0].json;
const rows = Array.isArray($json) ? $json : [];

const cursorMap = {};
for (const row of rows) {
  if (row && row.cursor_kind) {
    cursorMap[row.cursor_kind] = row.cursor_value;
  }
}

const backfillStart = cfg.backfill_start_at || '2022-09-01T00:00:00Z';
const backfillCreatedAt = cursorMap.leads_backfill_created_at || backfillStart;
const backfillDoneRaw = cursorMap.leads_backfill_done || '0';
const backfillDone =
  backfillDoneRaw === '1' || String(backfillDoneRaw).toLowerCase() === 'true';

const dailyLastRunAt = cursorMap.leads_daily_last_run_at || backfillStart;
const mode = backfillDone ? 'daily' : 'backfill';

return [{
  json: {
    mode,
    source: cfg.source || 'ingestion',
    entity: cfg.entity || 'Catalog_Лиды',
    backfill_created_at: backfillCreatedAt,
    daily_last_run_at: dailyLastRunAt,
    batch_size: Number(cfg.batch_size || 200),
    lookback_days: Number(cfg.daily_lookback_days || 3),
  },
}];

const payload = $json;
const rows = Array.isArray(payload?.value) ? payload.value : [];
const mode = $items('Decide mode', 0, 0)[0].json.mode;

return [{
  json: {
    ...payload,
    alert: rows.length === 0,
    alert_type: 'odata_zero_rows',
    alert_message: rows.length === 0
      ? `ALERT: OData returned 0 leads for ${mode} run`
      : null,
    rows_count: rows.length,
    mode,
  },
}];

const payload = $json;
const rows = Array.isArray(payload?.value) ? payload.value : [];
const mode = $items('Decide mode', 0, 0)[0].json.mode;

return [{
  json: {
    ...payload,
    alert: rows.length === 0,
    alert_type: 'odata_zero_rows',
    alert_message: rows.length === 0
      ? `ALERT: OData returned 0 leads for ${mode} run`
      : null,
    rows_count: rows.length,
    mode,
  },
}];

const payload = $json;
const rows = Array.isArray(payload.value) ? payload.value : [];
if (rows.length === 0) {
  return [{ json: { skipped: true, reason: '1C OData returned no rows', raw_payload: payload } }];
}

// --- БЕЗОПАСНОЕ ПОЛУЧЕНИЕ СПРАВОЧНИКОВ ---
const getItemsSafe = (nodeName) => {
  try {
    const data = $items(nodeName, 0, 0);
    return (data && data[0] && data[0].json && Array.isArray(data[0].json.value)) ? data[0].json.value : [];
  } catch (e) {
    return []; // Возвращаем пустой список, если нода еще не выполнилась или пуста
  }
};

const folderRows = getItemsSafe('Fetch lead folders');
const tagRows = getItemsSafe('Fetch tags catalog');
// ------------------------------------------

const tagsKey = '\u0422\u0435\u0433\u0438';
const notesKey = '\u041a\u043e\u043c\u043c\u0435\u043d\u0442\u0430\u0440\u0438\u0439';
const detailsKey = '\u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435\u0421\u0432\u0435\u0434\u0435\u043d\u0438\u044f';
const finishNotesKey = '\u0417\u0430\u043c\u0435\u0442\u043a\u0438\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f\u0420\u0430\u0431\u043e\u0442\u044b';
const companyKey = '\u041d\u0430\u0438\u043c\u0435\u043d\u043e\u0432\u0430\u043d\u0438\u0435\u041a\u043e\u043c\u043f\u0430\u043d\u0438\u0438';
const subjectKey = '\u0422\u0435\u043c\u0430';
const emailSearchKey = '\u0410\u0434\u0440\u0435\u0441\u042d\u041f\u0414\u043b\u044f\u041f\u043e\u0438\u0441\u043a\u0430';
const phoneSearchKey = '\u041d\u043e\u043c\u0435\u0440\u0422\u0435\u043b\u0435\u0444\u043e\u043d\u0430\u0414\u043b\u044f\u041f\u043e\u0438\u0441\u043a\u0430';
const contactInfoKey = '\u041a\u043e\u043d\u0442\u0430\u043a\u0442\u043d\u0430\u044f\u0418\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044f';
const emailKey = '\u0410\u0434\u0440\u0435\u0441\u042d\u041f';
const phoneKey = '\u041d\u043e\u043c\u0435\u0440\u0422\u0435\u043b\u0435\u0444\u043e\u043d\u0430';
const phoneShortKey = '\u041d\u043e\u043c\u0435\u0440\u0422\u0435\u043b\u0435\u0444\u043e\u043d\u0430\u0411\u0435\u0437\u041a\u043e\u0434\u043e\u0432';
const displayKey = '\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435';
const typeKey = '\u0422\u0438\u043f';
const serverDomainKey = '\u0414\u043e\u043c\u0435\u043d\u043d\u043e\u0435\u0418\u043c\u044f\u0421\u0435\u0440\u0432\u0435\u0440\u0430';
const finishVariantKey = '\u0412\u0430\u0440\u0438\u0430\u043d\u0442\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f';
const finishDateKey = '\u0414\u0430\u0442\u0430\u0417\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u0438\u044f\u0420\u0430\u0431\u043e\u0442\u044b';
const transferredKey = '\u041a\u043e\u043d\u0442\u0430\u043a\u0442\u044b\u041f\u0435\u0440\u0435\u043d\u0435\u0441\u0435\u043d\u044b';
const kindKey = '\u0412\u0438\u0434';
const extraAttrsKey = '\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435\u0420\u0435\u043a\u0432\u0438\u0437\u0438\u0442\u044b';
const tagRefKey = '\u0422\u0435\u0433_Key';

const dedupe = (arr) => [...new Set((arr || []).filter(Boolean))];
const normalizeEmail = (value) => typeof value === 'string' ? value.trim().toLowerCase() : '';
const normalizePhone = (value) => typeof value === 'string' ? value.replace(/\D/g, '') : '';
const looksLikeEmail = (value) => typeof value === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/i.test(value.trim());
const looksLikeSite = (value) => typeof value === 'string' && !!value.trim() && !/@/.test(value) && (/(https?:\/\/|www\.|[a-z0-9-]+\.[a-z]{2,})/i.test(value));
const looksLikePhoneDisplay = (value) => {
  if (typeof value !== 'string') return false;
  const digits = value.replace(/\D/g, '');
  return digits.length >= 10 && digits.length <= 15;
};
const splitMultiValue = (value) => {
  if (typeof value !== 'string') return [];
  return value
    .split(/[,;\n\r]+/)
    .map((x) => x.trim())
    .filter(Boolean);
};
const normalizeTags = (value, tagMap) => {
  const arr = Array.isArray(value) ? value : [];
  return dedupe(arr.map((item) => {
    if (typeof item === 'string') return item.trim();
    if (!item || typeof item !== 'object') return '';
    const key = typeof item[tagRefKey] === 'string' ? item[tagRefKey] : '';
    if (key && tagMap.has(key)) return tagMap.get(key);
    for (const prop of ['Description', 'Name', 'Code', '\u041f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435']) {
      if (typeof item[prop] === 'string' && item[prop].trim()) return item[prop].trim();
    }
    return '';
  }).filter(Boolean));
};
const collectExtraTextValues = (value) => {
  const arr = Array.isArray(value) ? value : [];
  return dedupe(arr.map((item) => {
    if (!item || typeof item !== 'object') return '';
    for (const prop of ['\u0422\u0435\u043a\u0441\u0442\u043e\u0432\u0430\u044f\u0421\u0442\u0440\u043e\u043a\u0430', '\u0417\u043d\u0430\u0447\u0435\u043d\u0438\u0435', 'Description', 'Name']) {
      if (typeof item[prop] === 'string' && item[prop].trim() && !/^[0-9a-f-]{36}$/i.test(item[prop].trim())) return item[prop].trim();
    }
    return '';
  }).filter(Boolean));
};

const folderMap = new Map();
for (const row of [...folderRows, ...rows]) {
  if (row && row.Ref_Key && row.Description && row.IsFolder) folderMap.set(row.Ref_Key, row.Description);
}
const tagMap = new Map();
for (const row of tagRows) {
  if (row && row.Ref_Key && typeof row.Description === 'string' && row.Description.trim()) {
    tagMap.set(row.Ref_Key, row.Description.trim());
  }
}

const extractChannels = (items) => {
  const rows = Array.isArray(items) ? items : [];
  const emails = [];
  const phones = [];
  const sites = [];
  const addresses = [];
  const channels = [];
  for (const item of rows) {
    if (!item || typeof item !== 'object') continue;
    const rawType = typeof item[typeKey] === 'string' ? item[typeKey].trim() : '';
    const type = rawType.toLowerCase();
    const display = typeof item[displayKey] === 'string' ? item[displayKey].trim() : '';
    const isPhoneType = type.includes('\u0442\u0435\u043b\u0435\u0444\u043e\u043d') || type.includes('\u0444\u0430\u043a\u0441');
    const isEmailType = type.includes('\u044d\u043b\u0435\u043a\u0442\u0440\u043e\u043d') || type.includes('mail');
    const isSiteType = type.includes('\u0432\u0435\u0431') || type.includes('\u0441\u0430\u0439\u0442');
    const isAddressType = type === '\u0430\u0434\u0440\u0435\u0441' || (type.includes('\u0430\u0434\u0440\u0435\u0441') && !type.includes('\u044d\u043b\u0435\u043a\u0442\u0440'));

    const email = normalizeEmail(item[emailKey] || (isEmailType && looksLikeEmail(display) ? display : ''));
    if (email && looksLikeEmail(email)) {
      emails.push(email);
      channels.push({ type: 'email', raw_type: rawType || null, value: email, display: display || null });
    }

    const phoneCandidates = [item[phoneKey], item[phoneShortKey]];
    if (isPhoneType && looksLikePhoneDisplay(display)) phoneCandidates.push(display);
    for (const candidate of phoneCandidates) {
      const phone = normalizePhone(candidate);
      if (!phone || phone.length < 10 || phone.length > 15) continue;
      phones.push(phone);
      channels.push({ type: 'phone', raw_type: rawType || null, value: phone, display: display || null });
    }

    const domain = typeof item[serverDomainKey] === 'string' ? item[serverDomainKey].trim() : '';
    const siteCandidate = isSiteType ? ((looksLikeSite(display) ? display : '') || domain) : '';
    if (siteCandidate) {
      sites.push(siteCandidate);
      channels.push({ type: 'site', raw_type: rawType || null, value: siteCandidate, display: display || null });
    }

    if (isAddressType && display) {
      addresses.push({ type: rawType || null, value: display });
      channels.push({ type: 'address', raw_type: rawType || null, value: display, display: display });
    }
  }
  return {
    emails: dedupe(emails),
    phones: dedupe(phones),
    sites: dedupe(sites),
    addresses,
    channels,
  };
};

return rows.map((row) => {
  const ownerName = row.Description || row[companyKey] || null;
  const isFolder = Boolean(row.IsFolder);
  const deleted = Boolean(row.DeletionMark);
  const channels = extractChannels(row[contactInfoKey]);
  const ownerSearchEmails = dedupe([
    ...splitMultiValue(row[emailSearchKey]).map(normalizeEmail).filter(looksLikeEmail),
    ...channels.emails,
  ]);
  const ownerSearchPhones = dedupe([
    ...splitMultiValue(row[phoneSearchKey]).map(normalizePhone).filter((x) => x && x.length >= 10 && x.length <= 15),
    ...channels.phones,
  ]);
  const notesParts = [row[notesKey], row[detailsKey], row[finishNotesKey]].filter((x) => typeof x === 'string' && x.trim());
  const ownerNotes = notesParts.join('\n').trim() || null;
  const ownerGroupPath = folderMap.get(row.Parent_Key) || null;
  const ownerTagsText = normalizeTags(row[tagsKey], tagMap);
  const extraAttrText = collectExtraTextValues(row[extraAttrsKey]);
  const textBlob = [ownerName, ownerNotes, row[finishVariantKey], row[kindKey], ownerGroupPath, ownerTagsText.join(' '), extraAttrText.join(' ')].filter(Boolean).join(' ').toLowerCase();
  const completed = Boolean((typeof row[finishDateKey] === 'string' && row[finishDateKey] && row[finishDateKey] !== '0001-01-01T00:00:00') || row[finishVariantKey] || textBlob.includes('\u0437\u0430\u0432\u0435\u0440\u0448'));
  const converted = Boolean(row[transferredKey]) || textBlob.includes('\u043f\u0435\u0440\u0435\u0432\u0435\u0434\u0435\u043d \u0432 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f') || textBlob.includes('\u043b\u0438\u0434 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b\u044f');
  const junk = textBlob.includes('\u0441\u043f\u0430\u043c') || textBlob.includes('\u043c\u0443\u0441\u043e\u0440') || textBlob.includes('\u043d\u0435\u0430\u043a\u0442\u0443\u0430\u043b');
  const digitsInSubject = String(row[subjectKey] || '').replace(/\D/g, '');
  const ownerInn = digitsInSubject.length >= 8 ? digitsInSubject : null;
  let importanceScore = 0;
  const reasons = [];
  if (ownerGroupPath && ownerGroupPath.toLowerCase().includes('\u0431\u0440\u0435\u043d\u0434')) { importanceScore += 50; reasons.push('group=\u0411\u0440\u0435\u043d\u0434\u044b'); }
  if (extraAttrText.some((x) => x.toLowerCase().includes('\u043a\u0440\u0443\u043f\u043d'))) { importanceScore += 25; reasons.push('extra=\u041a\u0440\u0443\u043f\u043d\u044b\u0439'); }
  if (ownerTagsText.length > 0) { importanceScore += 10; reasons.push('tags resolved'); }
  const ownerGroupPriorityHits = [
    '\u0434\u043e\u0441\u0442\u0430\u0432\u043a',
    '\u043f\u043e\u0434 \u043a\u043b\u044e\u0447',
    '\u043f\u0440\u043e\u0432\u0435\u0440'
  ].filter((needle) => ownerGroupPath && ownerGroupPath.toLowerCase().includes(needle));
  const ownerTagPriorityHits = ownerTagsText.filter((tag) => [
    '\u043a\u0440\u0443\u043f\u043d',
    '\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0441\u0442\u0432',
    '\u043c\u0430\u0440\u043a\u0435\u0442\u043f\u043b\u0435\u0439\u0441',
    '\u043a\u043e\u043d\u0435\u0447\u043d\u044b\u0439 \u043f\u043e\u043a\u0443\u043f\u0430\u0442\u0435\u043b',
    '\u0434\u043e\u0431\u0438\u0432'
  ].some((needle) => String(tag).toLowerCase().includes(needle)));
  const ownerTagDeprioritizeHits = ownerTagsText.filter((tag) => [
    '\u043c\u0435\u043b\u043e\u0447',
    '\u0442\u0435\u043d\u0434\u0435\u0440',
    '\u043f\u0435\u0440\u0435\u043f\u0440\u043e\u0434\u0430\u0436'
  ].some((needle) => String(tag).toLowerCase().includes(needle)));
  if (ownerGroupPriorityHits.length > 0) { importanceScore += 35; reasons.push('group=priority'); }
  if (ownerTagPriorityHits.length > 0) { importanceScore += 25; reasons.push(`tag=priority:${ownerTagPriorityHits.slice(0, 3).join(', ')}`); }
  if (ownerTagDeprioritizeHits.length > 0) { importanceScore -= 30; reasons.push(`tag=deprioritized:${ownerTagDeprioritizeHits.slice(0, 3).join(', ')}`); }
  if (ownerNotes && ownerNotes.length >= 80) { importanceScore += 20; reasons.push('rich notes'); }
  if (channels.sites.length > 0) { importanceScore += 10; reasons.push('site present'); }
  if (ownerSearchEmails.length + ownerSearchPhones.length >= 2) { importanceScore += 5; reasons.push('multiple owner channels'); }

  const fixRequired = (ownerSearchEmails.length === 0 || ownerSearchPhones.length === 0);
  if (fixRequired && !ownerTagsText.includes('fix_required')) ownerTagsText.push('fix_required');

  const skipped = !row.Ref_Key || !ownerName || deleted || isFolder;
  return {
    json: {
      skipped,
      owner_entity: 'Catalog_\u041b\u0438\u0434\u044b',
      owner_ref_key: row.Ref_Key,
      owner_name: ownerName,
      owner_display_name: row.Description || ownerName,
      owner_company_name: row[companyKey] || ownerName,
      owner_topic: row[subjectKey] || null,
      owner_source_key: row.Ref_Key,
      owner_inn: ownerInn,
      owner_group: row[kindKey] || null,
      owner_group_path: ownerGroupPath,
      owner_tags: Array.isArray(row[tagsKey]) ? row[tagsKey] : [],
      owner_tags_text: ownerTagsText,
      owner_notes: ownerNotes,
      owner_notes_compiled: ownerNotes,
      owner_address: channels.addresses.length ? channels.addresses[0].value : null,
      owner_site: channels.sites[0] || null,
      owner_sites: channels.sites,
      owner_addresses: channels.addresses,
      raw_payload: row,
      owner_source_entity: 'Catalog_\u041b\u0438\u0434\u044b',
      owner_status: converted ? 'converted' : (completed ? 'completed' : 'active'),
      owner_is_folder: isFolder,
      owner_is_buyer: null,
      owner_is_supplier: null,
      owner_classification: junk ? 'junk_candidate' : (converted ? 'converted_to_customer' : (completed ? 'completed_lead' : 'active_lead')),
      owner_is_junk: junk,
      owner_junk_reason: junk ? 'keyword in notes or name' : null,
      owner_converted_to_customer: converted,
      owner_search_emails: ownerSearchEmails,
      owner_search_phones: ownerSearchPhones,
      owner_contact_names: [],
      owner_contact_count: 0,
      owner_contact_emails: [],
      owner_contact_phones: [],
      owner_all_emails: ownerSearchEmails,
      owner_all_phones: ownerSearchPhones,
      owner_is_important: importanceScore >= 40,
      owner_importance_score: importanceScore,
      owner_importance_reason: reasons.length ? reasons.join('; ') : null
    }
  };
});

const decide = $items('Decide mode', 0, 0)[0].json;
const mode = decide.mode;
const batchSize = Number(decide.batch_size || 200);
const source = decide.source;
const entity = decide.entity;
const backfillPrev = decide.backfill_created_at;

const items = $input.all();
const createdValues = items
  .map((item) => item.json.owner_created_at)
  .filter((value) => typeof value === 'string' && value.length > 0)
  .map((value) => Date.parse(value))
  .filter((ms) => Number.isFinite(ms));

const maxCreatedAt = createdValues.length
  ? new Date(Math.max(...createdValues)).toISOString()
  : backfillPrev;

const ownersLoaded = items.length;

const fixRequiredIds = items
  .filter((item) => Array.isArray(item.json.owner_tags_text) && item.json.owner_tags_text.includes('fix_required'))
  .map((item) => item.json.owner_ref_key);

const backfillDone = mode === 'backfill' && ownersLoaded < batchSize;

return [{
  json: {
    mode,
    source,
    entity,
    owners_loaded: ownersLoaded,
    max_created_at: maxCreatedAt,
    backfill_done: backfillDone,
    fix_required_owner_ids: fixRequiredIds,
    run_finished_at: new Date().toISOString(),
  }
}];

