{{ (() => {
  const esc = (value) => String(value ?? '').replace(/'/g, "''");
  const source = esc($json.source);
  const entity = esc($json.entity);
  const runFinishedAt = esc($json.run_finished_at || new Date().toISOString());
  const backfillCreatedAt = esc($json.max_created_at || $json.backfill_created_at || '2022-09-01T00:00:00Z');
  const backfillDone = $json.mode === 'backfill'
    ? ($json.backfill_done ? '1' : '0')
    : '1';

  return `
WITH incoming(source, entity, cursor_kind, cursor_value, cursor_meta) AS (
  VALUES
    ('${source}', '${entity}', 'leads_daily_last_run_at', '${runFinishedAt}', '{}'::jsonb),
    ('${source}', '${entity}', 'leads_backfill_created_at', '${backfillCreatedAt}', '{}'::jsonb),
    ('${source}', '${entity}', 'leads_backfill_done', '${backfillDone}', '{}'::jsonb)
)
INSERT INTO ingestion_cursors(source, entity, cursor_kind, cursor_value, cursor_meta)
SELECT source, entity, cursor_kind, cursor_value, cursor_meta
FROM incoming
ON CONFLICT (source, entity, cursor_kind)
DO UPDATE SET
  cursor_value = EXCLUDED.cursor_value,
  cursor_meta = EXCLUDED.cursor_meta;
`;
})() }}

